"""Build the offline segment review page from shared course cards and storyboards.
The output has no external runtime dependencies; manifest.js supports file:// delivery.
"""
from pathlib import Path
import json
import argparse
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--root',type=Path,default=Path.cwd(),help='制作根目录，默认当前工作目录')
parser.add_argument('--repo',type=Path,default=Path.cwd(),help='包含scripts/testing-tutorial/course.json的课程仓库根目录，默认当前工作目录')
parser.add_argument('--link-record',type=Path,default=None,help='真实链接核验记录，默认制作根/evidence/review-link-check.json')
args=parser.parse_args()
ROOT=args.root.resolve()
REPO=args.repo.resolve()
LINK_RECORD=args.link_record.resolve() if args.link_record else ROOT/'evidence/review-link-check.json'
course_path=REPO/'scripts/testing-tutorial/course.json'
if not course_path.is_file():parser.error('找不到课程操作卡，请用--repo指定课程仓库根目录：'+str(course_path))
if not (ROOT/'segments.json').is_file():parser.error('找不到segments.json，请用--root指定制作根目录：'+str(ROOT))
source=json.loads((ROOT/'segments.json').read_text())
course=json.loads(course_path.read_text())
cards={step['id']:step for chapter in course['chapters'] for step in chapter['steps']}
link_file=LINK_RECORD
link_data=json.loads(link_file.read_text()) if link_file.exists() else {}
links={x['url']:{**x,'checked_at':link_data.get('checked_at')} for x in link_data.get('links',[])}
segments=[]
for seg in source['segments']:
 item={k:seg[k] for k in ['id','title','chapter','steps','evidence_gaps']}
 item['scenes']=[{k:scene[k] for k in ['id','headline','voice','kind','bullets','source_note','display_url','prompt'] if k in scene} for scene in seg['scenes']]
 item['prompts']=[{'id':i,'title':cards[i]['title'],'text':cards[i]['command']} for i in seg['steps'] if i in cards and cards[i].get('command_kind')=='prompt' and cards[i].get('command')]
 item['links']=[links.get(scene['display_url'],{'url':scene['display_url'],'result':'尚无本轮访问核验记录，目标页面待核验','authenticated_target_verified':False}) for scene in seg['scenes'] if scene.get('display_url')]
 segments.append(item)
html=r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>第一、第二章 · 分段视频审阅</title>
<style>
:root{--paper:#f6f1e7;--ink:#243a38;--green:#21745b;--line:#c7cebf;--soft:#e7ede2;--muted:#5c6861;--amber:#805400;--red:#a33d35}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--paper);font:18px/1.6 "Microsoft YaHei","PingFang SC",sans-serif}button,input,textarea,select{font:inherit}button,a{touch-action:manipulation}button{border:1px solid var(--line);background:transparent;color:var(--ink);border-radius:6px;padding:9px 15px;cursor:pointer}button:hover{background:var(--soft)}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--green);outline-offset:3px}button.primary{color:white;background:var(--green);border-color:var(--green)}button:disabled{opacity:.45;cursor:default}a{color:var(--green)}header{max-width:1440px;margin:auto;padding:26px 28px 18px;border-bottom:1px solid var(--line)}h1{font-size:32px;line-height:1.35;margin:0 0 9px}h2{font-size:26px;line-height:1.35;margin:7px 0 12px}h3{font-size:20px;margin:16px 0 9px}.lead{margin:6px 0 12px;color:var(--muted)}.summary{display:flex;flex-wrap:wrap;align-items:center;gap:9px 20px;font-size:15px}.top-actions{margin-top:16px;display:flex;gap:9px;flex-wrap:wrap}.badge{display:inline-block;line-height:1.5;border:1px solid var(--line);border-radius:4px;padding:2px 8px;font-size:13px;font-weight:400;color:var(--muted)}.badge.warn{border-color:#b7a77d;color:var(--amber)}.badge.good{border-color:var(--green);color:var(--green)}.layout{max-width:1440px;margin:auto;display:grid;grid-template-columns:330px minmax(0,1fr);gap:26px;padding:24px 28px}.chapters{min-width:0}.chapter-title{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:18px;margin:0 0 10px}.chapter-group{margin-bottom:24px}.segment{display:block;width:100%;text-align:left;background:transparent;border:1px solid var(--line);border-radius:7px;margin:0 0 10px;padding:12px}.segment[aria-current=true]{border-color:var(--green);box-shadow:inset 4px 0 var(--green);background:var(--soft)}.segment-id{font:13px/1.4 ui-monospace,monospace;letter-spacing:.03em;color:var(--green)}.segment-title{display:block;font-size:17px;line-height:1.5;margin:4px 0 8px}.segment-meta{display:flex;gap:5px;flex-wrap:wrap}.small{font-size:14px;color:var(--muted)}main{min-width:0}.segment-head{display:flex;gap:14px;justify-content:space-between;align-items:flex-start}.number{font:15px/1.5 ui-monospace,monospace;color:var(--green)}.status-line{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px}.video-box{position:relative;background:#1e302e;border:1px solid #243a38;border-radius:7px;overflow:hidden;aspect-ratio:16/9}.video-box video{display:block;width:100%;height:100%;background:#1e302e}.media-message{margin:0;color:var(--muted);font-size:15px;min-height:26px;padding-top:8px}.media-message.error{color:var(--red)}.video-links{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin:6px 0 13px;font-size:15px}.not-ready{color:var(--amber)}.note-panel{border:1px solid var(--line);border-radius:7px;padding:18px 20px;margin:20px 0;background:rgba(255,255,255,.24)}.form-row{display:flex;gap:14px;align-items:end;flex-wrap:wrap}.field{display:flex;flex-direction:column;gap:5px;flex:1 1 140px}.field.time{flex:0 1 150px}.field label{font-size:15px;color:var(--muted)}input,textarea,select{width:100%;border:1px solid var(--line);border-radius:5px;color:var(--ink);background:#fffdf8;padding:9px 12px}textarea{min-height:118px;resize:vertical;margin-top:7px;line-height:1.6}.note-buttons{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:12px}.form-feedback{font-size:14px;color:var(--green);min-height:24px;margin:8px 0 0}.form-feedback.error{color:var(--red)}.review-list{list-style:none;padding:0;margin:10px 0}.review-item{padding:14px 0;border-top:1px solid var(--line)}.review-item p{margin:6px 0;white-space:pre-wrap;overflow-wrap:anywhere}.review-item-top{display:flex;gap:9px;align-items:center;justify-content:space-between}.review-item button{font-size:14px;padding:4px 10px}.review-item .when{font:14px/1.5 ui-monospace,monospace}.decision{display:flex;align-items:center;gap:10px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:15px}.decision select{max-width:230px}.decision label{font-size:15px}.source{font-size:14px;padding:14px 0;border-top:1px solid var(--line);color:var(--muted)}.source summary{cursor:pointer;color:var(--ink);font-size:16px}.source ul{padding-left:22px}.source li{margin-bottom:7px}.footer-nav{display:flex;justify-content:space-between;gap:15px;margin-top:18px}footer{max-width:1440px;margin:auto;padding:14px 28px 30px;border-top:1px solid var(--line);font-size:14px;color:var(--muted)}.hidden{display:none!important}.file-load{font-size:14px;cursor:pointer;color:var(--green);text-decoration:underline}.file-load input{position:absolute;width:1px;height:1px;overflow:hidden;opacity:0}.manifest-note{max-width:100%;overflow-wrap:anywhere}.help{font-size:14px;color:var(--muted);margin:9px 0}.plain-list{padding-left:20px}.empty{color:var(--muted);font-size:15px}.wordbreak{overflow-wrap:anywhere}.save-note{font-size:14px;color:var(--muted)}.script-scene{padding:12px 0;border-bottom:1px dashed var(--line)}.script-scene h4{font-size:17px;margin:0 0 7px}.script-scene p{margin:6px 0;white-space:pre-wrap}.prompt-text{font-size:15px;min-height:145px;margin:8px 0;background:#fffdf8}.copy-prompt{font-size:14px;padding:5px 11px}.url-check{padding:9px 0;border-bottom:1px dashed var(--line)}.url-check a{overflow-wrap:anywhere}.url-check p{margin:4px 0}.script-section>summary{font-weight:600}
@media(max-width:900px){header{padding:20px 18px 15px}h1{font-size:27px}.layout{grid-template-columns:1fr;padding:18px;gap:10px}.chapters{border-bottom:1px solid var(--line)}.chapter-group{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-bottom:16px}.chapter-title{grid-column:1/-1;margin:0}.segment{margin:0;height:100%}.segment-title{font-size:16px}.segment-meta .badge{font-size:12px}h2{font-size:23px}.note-panel{padding:15px}footer{padding:15px 18px}.form-row{gap:9px}}@media(max-width:520px){.chapter-group{display:block}.chapter-title{margin-bottom:9px}.segment{margin-bottom:8px}.segment-title{margin:2px 0 5px}.segment{padding:9px 12px}.summary{gap:6px 12px}.top-actions button{font-size:15px;padding:7px 10px}.video-links{gap:10px}.status-line{gap:5px}.form-row .field{flex-basis:100%}.form-row .field.time{flex:1 1 125px}.form-row button{flex:1 1 150px}.decision select{max-width:none;flex:1}.segment-head{display:block}.footer-nav button{font-size:16px}.note-buttons{align-items:stretch}.note-buttons button{flex:1}.review-item-top{align-items:flex-start}.source{font-size:13px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style></head><body>
<header><h1>第一、第二章 · 分段视频审阅</h1><p class="lead">按段看、按时间点提意见。修改时只替换受影响的小段，其他段保持原版本。</p><div class="summary"><span id="manifest-status" class="manifest-note">交付清单：正在读取</span><span id="overall-duration">两章实际时长：待生成</span><span>9个独立片段 · 其余章节暂缓</span></div><div class="top-actions"><a href="../textbook/index.html">打开配套教材</a><button id="refresh">刷新版本与时长</button><button id="export" class="primary">导出审阅意见</button><label class="file-load hidden">离线时选择交付清单<input id="manifest-file" type="file" accept="application/json,.json"></label></div><p class="help">意见仅保存在当前浏览器，不会自动发送。正式时长从交付清单读取，不采用文案估算。</p></header>
<div class="layout"><nav class="chapters" id="chapters" aria-label="分章片段"></nav><main>
<div class="segment-head"><div><div class="number" id="active-id"></div><h2 id="active-title"></h2></div><span id="active-review" class="badge warn">待审核</span></div>
<div class="status-line"><span id="active-duration" class="badge">实际时长：待生成</span><span class="badge warn">素材状态：实录待补</span><span id="active-version" class="badge">版本：待生成</span></div>
<div class="video-box"><video id="video" poster="../evidence/frames/c1-s01-t010.000.png" controls preload="metadata" playsinline aria-label="当前片段视频"></video></div><p class="media-message" id="media-message" role="status">正在检查本段交付文件。</p><div class="video-links"><a id="video-link" target="_blank" rel="noopener">单独打开这段视频</a><span id="audio-status" class="small">声音状态：以实际交付为准</span></div>
<details class="source"><summary>素材范围与待补项</summary><p>操作路径示意、历史数据及本机组件演示按画面标注区分。当前登录后设置、线上CDS与现场自动化实录尚未齐全，不能把本页审片意见当作系统验收通过。</p><ul id="gaps"></ul><div class="small" id="active-sha"></div></details>
<details class="source script-section"><summary>配套文案 / 提示词（可展开、可复制）</summary><p>文案与当前制作分段一致；长提示词用于交给Agent，不需要学员逐字输入或操作代码。</p><div id="script-scenes"></div><h3>交给Agent的提示词</h3><div id="script-prompts"></div><h3>入口核验记录</h3><p>以下区分公开入口、登录跳转与已登录目标页。到达登录页不代表目标设置已核验。</p><div id="url-checks"></div></details>
<section class="note-panel" aria-label="记录本段意见"><h3>记录这一段的修改意见</h3><div class="form-row"><div class="field time"><label for="note-time">时间点</label><input id="note-time" type="text" inputmode="decimal" value="00:00" placeholder="例如 01:12" autocomplete="off"></div><button id="capture-time">使用当前播放时间</button><div class="field"><label for="note-kind">意见类型</label><select id="note-kind"><option value="content">文案与表达</option><option value="pace">节奏与停顿</option><option value="visual">画面与圈注</option><option value="operation">操作是否能跟做</option><option value="audio">声音与字幕</option><option value="other">其他</option></select></div></div><label for="note-text" class="small">希望怎样修改</label><textarea id="note-text" placeholder="例如：这句话太快，展示仓库名后再多停两秒。"></textarea><div class="note-buttons"><button id="save-note" class="primary">保存这条意见</button><span class="save-note">记录会附上当前片段编号、时间点和已读取的版本。</span></div><p id="form-feedback" class="form-feedback" role="status"></p><div class="decision"><label for="decision">本段审阅结论</label><select id="decision"><option value="pending">待审核</option><option value="changes_requested">需要修改</option><option value="approved">本段可以接受</option></select><span class="small">这是视频审片记录，仍保留素材待补状态。</span></div></section>
<section aria-label="本段已保存意见"><h3>本段意见 <span id="note-count" class="small"></span></h3><ul id="notes" class="review-list"></ul></section><div class="footer-nav"><button id="previous">上一段</button><button id="next">下一段</button></div>
</main></div><footer>直接打开本页即可观看已交付的视频文件和记录意见。版本与时长通过资料包中的交付清单自动加载；无需编辑文件或操作代码。</footer>
<script src="../delivery-manifest.js"></script>
<script>
'use strict';
const SEGMENTS=__SEGMENTS__;
const STORE_KEY='testing-course-segment-review-v1';
const $=id=>document.getElementById(id);
let pendingSeek=null;
let current=0,manifest=window.__DELIVERY_MANIFEST&&typeof window.__DELIVERY_MANIFEST==='object'&&!Array.isArray(window.__DELIVERY_MANIFEST)?window.__DELIVERY_MANIFEST:null,manifestState=window.__DELIVERY_MANIFEST&&typeof window.__DELIVERY_MANIFEST==='object'&&!Array.isArray(window.__DELIVERY_MANIFEST)?'loaded':'pending',records={notes:[],decisions:{}},loaded=false;
try{const old=JSON.parse(localStorage.getItem(STORE_KEY)||'null');if(old&&Array.isArray(old.notes)&&old.decisions&&typeof old.decisions==='object')records=old;}catch{}
const labels={pending:'待审核',changes_requested:'需要修改',approved:'本段可以接受'};
const kindLabels={content:'文案与表达',pace:'节奏与停顿',visual:'画面与圈注',operation:'操作是否能跟做',audio:'声音与字幕',other:'其他'};
function safeString(v){return typeof v==='string'||typeof v==='number'?String(v):'';}
function number(v){if(typeof v==='string'&&!/^\d+(?:\.\d+)?$/.test(v.trim()))return null;const n=Number(v);return Number.isFinite(n)&&n>0?n:null;}
function formatTime(n){n=Math.max(0,Math.floor(Number(n)||0));const h=Math.floor(n/3600),m=Math.floor((n%3600)/60),s=n%60;return(h?h+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
function parseTime(t){t=t.trim();if(/^\d+(?:\.\d+)?$/.test(t))return Number(t);if(!/^\d{1,3}:\d{1,2}(?::\d{1,2})?$/.test(t))return null;const a=t.split(':').map(Number);if(a.slice(1).some(n=>n>59))return null;return a.reduce((x,y)=>x*60+y,0);}
function allEntries(){if(!manifest)return[];const result=[];for(const key of ['segments','videos','files','outputs']){const v=manifest[key];if(Array.isArray(v))result.push(...v);else if(v&&typeof v==='object')for(const[id,obj]of Object.entries(v))if(obj&&typeof obj==='object')result.push({id,...obj});}return result.filter(x=>x&&typeof x==='object');}
function entry(id){return allEntries().find(x=>x.id===id||x.segment_id===id||[x.path,x.file,x.filename,x.output,x.video].some(p=>typeof p==='string'&&(p.endsWith('/'+id+'.mp4')||p===id+'.mp4')))||null;}
function rootVersion(){if(!manifest)return null;return safeString(manifest.version||manifest.build_id||manifest.revision||manifest.source_commit)||null;}
function info(id){const e=entry(id)||{};let duration=null;for(const v of[e.actual_duration_seconds,e.duration_seconds,e.media?.duration_seconds,e.probe?.duration,e.duration]){duration=number(v);if(duration!==null)break;}const version=safeString(e.version||e.source_commit||rootVersion())||null;const sha=safeString(e.sha256||e.sha256sum)||null;let audio=null;if(typeof e.has_audio==='boolean')audio=e.has_audio;else if(typeof e.audio_tracks==='number')audio=e.audio_tracks>0;else if(typeof manifest?.sample_audio_tracks==='number')audio=manifest.sample_audio_tracks>0;return {duration,version,sha,audio,audio_quality:safeString(e.audio_quality||e.quality||manifest?.quality)||null,exists:!!entry(id)};}
function isAudioRejected(id){return manifest?.status==='audio_rejected_by_user'||manifest?.quality==='audio_rejected'||info(id).audio_quality==='audio_rejected';}
function mediaPath(id){if(manifestState!=='loaded'||!manifest)return null;return isAudioRejected(id)?'../visual-materials/'+id+'-silent.mp4':'../videos/'+id+'.mp4';}
function syncMedia(){const id=SEGMENTS[current].id,path=mediaPath(id),v=$('video');v.poster='../evidence/frames/'+id+'-t010.000.png';if(!path){v.pause();v.removeAttribute('src');v.load();$('media-message').textContent='交付清单尚未载入，暂不播放；旧配音不会自动加载。';return;}if(v.getAttribute('src')!==path){v.pause();loaded=false;v.src=path;v.load();$('media-message').className='media-message';$('media-message').textContent=isAudioRejected(id)?'正在加载无声画面审阅版，旧配音已停用。':'正在检查本段交付文件。';}}
function effectiveDecision(id){const d=records.decisions[id];if(!d)return'pending';const now=info(id);if(d.sha&&now.sha&&d.sha!==now.sha)return'pending';if(d.version&&now.version&&d.version!==now.version)return'pending';if(d.value==='approved'&&!(now.exists&&now.sha&&now.duration!==null&&now.audio_quality!=='audio_rejected'))return'pending';return labels[d.value]?d.value:'pending';}
function save(){try{localStorage.setItem(STORE_KEY,JSON.stringify(records));return true;}catch{return false;}}
function badge(text,cls=''){const s=document.createElement('span');s.className='badge '+cls;s.textContent=text;return s;}
function renderNav(){const nav=$('chapters');nav.replaceChildren();for(const chapter of[1,2]){const group=document.createElement('section');group.className='chapter-group';const title=document.createElement('h3');title.className='chapter-title';const name=document.createElement('span');name.textContent=chapter===1?'第一章 · Codex代码审查':'第二章 · 视觉验收';const total=document.createElement('small');const list=SEGMENTS.filter(s=>s.chapter===chapter);const durations=list.map(s=>info(s.id).duration);total.textContent=durations.every(x=>x!==null)?formatTime(durations.reduce((a,b)=>a+b,0)):'时长待生成';title.append(name,total);group.append(title);for(const seg of list){const i=SEGMENTS.findIndex(s=>s.id===seg.id);const b=document.createElement('button');b.type='button';b.className='segment';b.dataset.segment=seg.id;b.setAttribute('aria-current',i===current?'true':'false');const id=document.createElement('span');id.className='segment-id';id.textContent=seg.id;const label=document.createElement('span');label.className='segment-title';label.textContent=seg.title;const meta=document.createElement('span');meta.className='segment-meta';const n=info(seg.id),decision=effectiveDecision(seg.id);meta.append(badge(labels[decision],decision==='approved'?'good':'warn'),badge(n.duration!==null?formatTime(n.duration):'时长待生成'),badge('实录待补','warn'));b.append(id,label,meta);b.addEventListener('click',()=>select(i));group.append(b);}nav.append(group);}}
function renderManifest(){const version=rootVersion();$('manifest-status').textContent=manifestState==='loaded'?'交付版本：'+(version||'待生成（清单尚无版本）'):'交付版本：待生成（尚未读取交付清单）';const durations=SEGMENTS.map(s=>info(s.id).duration);$('overall-duration').textContent=manifest?.quality==='audio_rejected'?'当前中文配音未通过；总时长待新声音后重排':durations.every(x=>x!==null)?'两章实际时长：'+formatTime(durations.reduce((a,b)=>a+b,0)):'两章实际时长：待生成';}
function renderNotes(){const seg=SEGMENTS[current],list=records.notes.filter(n=>n.segment_id===seg.id);$('note-count').textContent=list.length?'（'+list.length+'条）':'';$('notes').replaceChildren();if(!list.length){const li=document.createElement('li');li.className='empty';li.textContent='这一段还没有记录意见。';$('notes').append(li);return;}for(const n of list){const li=document.createElement('li');li.className='review-item';const top=document.createElement('div');top.className='review-item-top';const when=document.createElement('button');when.className='when';when.textContent=formatTime(n.seconds)+' · '+(kindLabels[n.kind]||'其他');when.title='跳到这条意见的时间点';when.addEventListener('click',()=>{if(loaded){$('video').currentTime=n.seconds;$('video').pause();}else feedback('视频尚未加载，先确认该段文件已交付。',true);});const del=document.createElement('button');del.textContent='删除';del.setAttribute('aria-label','删除'+formatTime(n.seconds)+'这条意见');del.addEventListener('click',()=>{records.notes=records.notes.filter(x=>x.id!==n.id);save();renderNotes();});top.append(when,del);const text=document.createElement('p');text.textContent=n.text;const version=document.createElement('div');version.className='small wordbreak';version.textContent='记录版本：'+(n.version||'待生成／未读取')+(n.sha?' · '+n.sha.slice(0,12):'');li.append(top,text,version);$('notes').append(li);}}
function renderCompanion(){const seg=SEGMENTS[current];$('script-scenes').replaceChildren();for(const scene of seg.scenes){const wrap=document.createElement('section');wrap.className='script-scene';const title=document.createElement('h4');title.textContent=scene.headline;const content=document.createElement('p');content.textContent=scene.voice||'本幕为无声阅读停顿卡。';const note=document.createElement('div');note.className='small';note.textContent=scene.source_note||'画面内容以当前分段标注为准。';wrap.append(title,content,note);if(scene.prompt){const extra=document.createElement('p');extra.textContent=scene.prompt;wrap.append(extra);}$('script-scenes').append(wrap);}$('script-prompts').replaceChildren();if(!seg.prompts.length){const no=document.createElement('p');no.textContent='本段没有需要复制的Agent提示词。';$('script-prompts').append(no);}for(const p of seg.prompts){const wrap=document.createElement('section');wrap.className='script-scene';const title=document.createElement('h4');title.textContent=p.id+' · '+p.title;const text=document.createElement('textarea');text.className='prompt-text';text.readOnly=true;text.value=p.text;text.setAttribute('aria-label',p.id+'提示词');const copy=document.createElement('button');copy.className='copy-prompt';copy.textContent='复制这条提示词';const feedback=document.createElement('span');feedback.className='small';feedback.setAttribute('role','status');copy.addEventListener('click',async()=>{try{if(!navigator.clipboard?.writeText)throw new Error('fallback');await navigator.clipboard.writeText(p.text);feedback.textContent=' 已复制，可以交给Agent。';}catch{text.focus();text.select();let ok=false;try{ok=document.execCommand('copy');}catch{}feedback.textContent=ok?' 已复制，可以交给Agent。':' 已选中文字，请使用浏览器的复制操作。';}});wrap.append(title,text,copy,feedback);$('script-prompts').append(wrap);}$('url-checks').replaceChildren();if(!seg.links.length){const p=document.createElement('p');p.textContent='本段没有固定公开入口；由Agent返回本项目实际页面与核验状态，不猜测实例域名。';$('url-checks').append(p);}for(const link of seg.links){const wrap=document.createElement('section');wrap.className='url-check';const a=document.createElement('a');a.href=link.url;a.target='_blank';a.rel='noopener';a.textContent=link.url;const p=document.createElement('p');p.textContent=link.result;const label=document.createElement('div');label.className='small';label.textContent='登录后目标页：'+(link.authenticated_target_verified?'已核验':'待核验')+(link.checked_at?' · 记录时间：'+link.checked_at:'');wrap.append(a,p,label);$('url-checks').append(wrap);}}
function renderActive(){const s=SEGMENTS[current],n=info(s.id);$('active-id').textContent=s.id+' · 第'+(current+1)+' / '+SEGMENTS.length+'段';$('active-title').textContent=s.title;const decision=effectiveDecision(s.id);$('active-review').textContent=labels[decision];$('active-review').className='badge '+(decision==='approved'?'good':'warn');$('decision').value=decision;$('active-duration').textContent=n.duration!==null?(n.audio_quality==='audio_rejected'?'当前配音版时长（待重排）：':'实际时长：')+formatTime(n.duration):'实际时长：待生成';$('active-version').textContent='版本：'+(n.version||'待生成');$('audio-status').textContent=isAudioRejected(s.id)?'无声画面审阅版；旧配音已停用，配音待官方API':n.audio===false?'字幕审阅版 · 当前无音轨':n.audio===true?'清单记录含音轨，请结合实际播放审阅':'声音状态：以实际交付为准';$('active-sha').textContent=n.sha?'本段文件校验：'+n.sha:'本段文件校验：待生成';$('gaps').replaceChildren();for(const gap of s.evidence_gaps){const li=document.createElement('li');li.textContent=gap;$('gaps').append(li);}$('previous').disabled=current===0;$('next').disabled=current===SEGMENTS.length-1;const media=mediaPath(s.id);if(media)$('video-link').href=media;else $('video-link').removeAttribute('href');$('video-link').textContent=isAudioRejected(s.id)?'单独打开这段无声画面':'单独打开这段视频';renderNotes();renderCompanion();}
function feedback(text,error=false){$('form-feedback').textContent=text;$('form-feedback').classList.toggle('error',error);}
function select(i){if(i<0||i>=SEGMENTS.length)return;if(pendingSeek&&pendingSeek.id!==SEGMENTS[i].id)pendingSeek=null;if($('note-text').value.trim()){feedback('当前尚有未保存文字，请先保存这条意见再切换片段。',true);$('note-text').focus();return;}const v=$('video');v.pause();current=i;loaded=false;$('note-time').value='00:00';feedback('');$('media-message').className='media-message';$('media-message').textContent='正在检查本段交付文件。';syncMedia();renderNav();renderActive();const path=new URL(location.href);path.searchParams.delete('segment');path.searchParams.delete('t');path.hash=SEGMENTS[current].id;try{history.replaceState(null,'',path);}catch{}}
async function loadManifest(){manifestState='pending';renderManifest();try{const r=await fetch('../delivery-manifest.json',{cache:'no-store'});if(!r.ok)throw new Error('manifest HTTP '+r.status);const data=await r.json();if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('invalid manifest');manifest=data;manifestState='loaded';}catch{const cached=window.__DELIVERY_MANIFEST;if(cached&&typeof cached==='object'&&!Array.isArray(cached)){manifest=cached;manifestState='loaded';}else{manifest=null;manifestState='unavailable';}}renderManifest();renderNav();renderActive();syncMedia();}
$('video').addEventListener('loadedmetadata',()=>{loaded=true;if(pendingSeek&&pendingSeek.id===SEGMENTS[current].id){const target=pendingSeek.seconds;pendingSeek=null;if(Number.isFinite($('video').duration)&&target<=$('video').duration){$('video').currentTime=target;$('video').pause();$('note-time').value=formatTime(target);}}$('media-message').className='media-message';$('media-message').textContent='本段视频已加载。正式时长与版本以上方交付清单为准。';});
$('video').addEventListener('error',()=>{loaded=false;$('media-message').className='media-message error';$('media-message').textContent='视频待生成，或当前未能加载该交付文件。请保留资料包目录结构；不代表本段已制作完成。';});
$('capture-time').addEventListener('click',()=>{if(!loaded){feedback('视频尚未加载，可先手填希望标记的时间点。',true);return;}$('note-time').value=formatTime($('video').currentTime);feedback('已使用当前播放时间。');});
$('save-note').addEventListener('click',()=>{const text=$('note-text').value.trim(),seconds=parseTime($('note-time').value);if(!text){feedback('请写下希望怎样修改。',true);$('note-text').focus();return;}if(seconds===null||!Number.isFinite(seconds)||seconds<0){feedback('时间请写成01:12这样的分:秒，或直接填写秒数。',true);return;}const seg=SEGMENTS[current],n=info(seg.id);if(n.duration!==null&&seconds>n.duration){feedback('这个时间点超过清单记录的本段实际时长。',true);return;}records.notes.push({id:'note-'+Date.now()+'-'+records.notes.length,segment_id:seg.id,chapter:seg.chapter,title:seg.title,seconds,kind:$('note-kind').value,text,version:n.version,sha:n.sha,recorded_at:new Date().toISOString()});const ok=save();$('note-text').value='';renderNotes();feedback(ok?'已保存到当前浏览器，可继续记录或导出。':'当前浏览器不能持久保存，请及时导出审阅意见。',!ok);});
$('decision').addEventListener('change',()=>{const s=SEGMENTS[current],n=info(s.id),value=$('decision').value;if(value==='approved'&&!(n.exists&&n.sha&&n.duration!==null&&n.audio_quality!=='audio_rejected')){$('decision').value='pending';feedback('本段尚未满足接受条件，或当前中文配音已被拒绝；请先保存文案与画面意见，等待新版声音与成片。',true);return;}records.decisions[s.id]={value,version:n.version,sha:n.sha,recorded_at:new Date().toISOString()};const ok=save();renderNav();renderActive();feedback(ok?'本段审阅结论已保存。':'当前浏览器不能持久保存，请及时导出。',!ok);});
$('export').addEventListener('click',()=>{const pending=$('note-text').value.trim();const output={schema:1,kind:'视频分段审阅意见；不等于系统验收结论',exported_at:new Date().toISOString(),delivery_version:rootVersion(),manifest_state:manifestState,segments:SEGMENTS.map(s=>({id:s.id,title:s.title,chapter:s.chapter,delivery:info(s.id),decision:records.decisions[s.id]||{value:'pending'},notes:records.notes.filter(n=>n.segment_id===s.id)})),unsaved_draft:pending?{segment_id:SEGMENTS[current].id,time:$('note-time').value,text:pending}:null};const blob=new Blob([JSON.stringify(output,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='第一二章-分段审阅意见.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);feedback('已导出；如需交回制作，请发送这个意见文件。');});
$('refresh').addEventListener('click',loadManifest);
$('manifest-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('invalid');manifest=data;manifestState='loaded';renderManifest();renderNav();renderActive();syncMedia();feedback('交付清单已读取，版本和实际时长已按清单刷新。');}catch{feedback('未读到有效交付清单，请选择资料包中的delivery-manifest.json。',true);}finally{e.target.value='';}});
$('previous').addEventListener('click',()=>select(current-1));$('next').addEventListener('click',()=>select(current+1));
const params=new URLSearchParams(location.search),requestedId=params.get('segment')||location.hash.slice(1);const requested=SEGMENTS.findIndex(s=>s.id===requestedId);if(requested>=0){current=requested;const raw=params.get('t');if(raw!==null&&/^\d+(?:\.\d+)?$/.test(raw)){const seconds=Number(raw);if(Number.isFinite(seconds)&&seconds>=0)pendingSeek={id:SEGMENTS[current].id,seconds};}}
renderNav();renderManifest();renderActive();select(current);loadManifest();
window.__segmentReview={segments:SEGMENTS,get current(){return SEGMENTS[current].id;},get manifestState(){return manifestState;},get records(){return JSON.parse(JSON.stringify(records));},select(id){const i=SEGMENTS.findIndex(s=>s.id===id);if(i>=0)select(i);},parseTime,formatTime,info};
</script></body></html>'''
(ROOT/'review').mkdir(parents=True,exist_ok=True)
(ROOT/'review/index.html').write_text(html.replace('__SEGMENTS__',json.dumps(segments,ensure_ascii=False).replace('</','<\\/')))
print(ROOT/'review/index.html')
